// The status mark: one shape + word per state, used by the connection badge
// and every run row, so state never reads by colour alone.
// Kinds: passed (dot) · failed (diamond) · idle (ring).
export function mark(kind, label) {
  return `<span class="mark mark--${kind}"><span class="mark__shape" aria-hidden="true"></span>${label}</span>`;
}

// ponytail: there is no live connection yet (no /api/health on the server), so the
// badge says so instead of showing a green "Connected". Swap to health() when wired.
export function renderBadge() {
  return `<span class="badge" title="Runs below are sample data. The API is not connected yet.">${
    mark('idle', 'Sample data')
  }</span>`;
}

