import { renderBadge, mark } from './components/StatusBadge.js';

// The whole runs table. Nothing behind it.
const RUNS = [
  { id: 'r-1041', service: 'checkout', status: 'passed', started: '09:12', duration: '2m 41s' },
  { id: 'r-1040', service: 'billing',  status: 'failed', started: '08:58', duration: '1m 07s' },
  { id: 'r-1039', service: 'catalog',  status: 'passed', started: '08:31', duration: '3m 22s' },
  { id: 'r-1038', service: 'notify',   status: 'passed', started: '08:04', duration: '0m 51s' },
];

const LABEL = { passed: 'Passed', failed: 'Failed' };

function row(r) {
  return `<tr class="run run--${r.status}">
    <th scope="row" class="id">${r.id}</th>
    <td>${r.service}</td>
    <td>${mark(r.status, LABEL[r.status])}</td>
    <td class="num">${r.started}</td>
    <td class="num">${r.duration}</td>
    <td class="act"><button data-run="${r.id}" class="btn retry" aria-label="Retry ${r.id}">Retry</button></td>
  </tr>`;
}

function summary() {
  const failed = RUNS.filter((r) => r.status === 'failed').length;
  const runs = `${RUNS.length} ${RUNS.length === 1 ? 'run' : 'runs'}`;
  return failed ? `${runs} · ${mark('failed', `${failed} failed`)}` : `${runs} · ${mark('passed', 'all passed')}`;
}

function table() {
  if (!RUNS.length) {
    return `<div class="empty">${mark('idle', 'No runs yet')}<p>Start one with New run.</p></div>`;
  }
  return `<div class="table-wrap"><table>
    <thead><tr>
      <th scope="col">Run</th><th scope="col">Service</th><th scope="col">Status</th>
      <th scope="col" class="num">Started</th><th scope="col" class="num">Duration</th>
      <th scope="col" class="act"><span class="sr-only">Actions</span></th>
    </tr></thead>
    <tbody>${RUNS.map(row).join('')}</tbody>
  </table></div>`;
}

export function render() {
  document.querySelector('#app').innerHTML = `
    <header class="bar">
      <span class="wordmark">pulse</span>
      ${renderBadge()}
    </header>
    <main>
      <div class="head">
        <div>
          <h1>Deploy runs</h1>
          <p class="summary">${RUNS.length ? summary() : ''}</p>
        </div>
        <button id="new-run" class="btn primary">New run</button>
      </div>
      <p id="notice" class="notice" role="status"></p>
      ${table()}
      <p class="foot">Sample data. Retry and New run are not connected to the API yet.</p>
    </main>`;

  // ponytail: buttons still aren't wired (backend ticket), so they say so instead of
  // silently logging. Replace with retryRun/createRun from src/api/client.js.
  const notice = document.querySelector('#notice');
  const say = (msg) => { notice.textContent = msg; };
  document.querySelectorAll('.retry').forEach((b) => {
    b.addEventListener('click', () => say(`Retry for ${b.dataset.run} was not sent: the API is not connected yet.`));
  });
  document.querySelector('#new-run')
    .addEventListener('click', () => say('New run was not started: the API is not connected yet.'));
}

render();

