:root {
  color-scheme: dark;
  --bg: oklch(0.17 0.012 250);
  --surface: oklch(0.205 0.012 250);
  --hover: oklch(0.235 0.014 250);
  --ink: oklch(0.94 0.006 250);
  --muted: oklch(0.76 0.012 250);
  --line: oklch(0.28 0.012 250);   /* row separators: decorative, not a control edge */
  --edge: oklch(0.52 0.014 250);   /* control borders, >=3:1 on bg and surface */
  --accent: oklch(0.74 0.13 250);
  --on-accent: oklch(0.17 0.02 250);
  --ok: oklch(0.80 0.15 150);
  --bad: oklch(0.72 0.17 25);
  --idle: var(--muted);
  --ring: oklch(0.84 0.1 250);
  --mono: ui-monospace, 'SF Mono', 'Cascadia Mono', Menlo, Consolas, monospace;
}

* { box-sizing: border-box; }
html { scroll-padding-top: 3rem; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 0.9375rem/1.5 system-ui, -apple-system, 'Segoe UI', sans-serif;
  -webkit-font-smoothing: antialiased;
}
::selection { background: var(--accent); color: var(--on-accent); }
:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }

.sr-only {
  position: absolute; width: 1px; height: 1px; overflow: hidden;
  clip: rect(0 0 0 0); white-space: nowrap;
}

/* Top bar */
.bar {
  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
  padding: 0.75rem 1.5rem;
  border-bottom: 1px solid var(--line);
}
.wordmark { font-weight: 650; letter-spacing: -0.01em; font-size: 1rem; }
.badge {
  padding: 0.25rem 0.625rem;
  border: 1px solid var(--edge);
  border-radius: 999px;
  font-size: 0.8125rem;
  color: var(--muted);
}

main { max-width: 72rem; margin: 0 auto; padding: 2rem 1.5rem 3rem; }

.head {
  display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between;
  gap: 1rem; margin-bottom: 1.25rem;
}
h1 { margin: 0; font-size: 1.5rem; line-height: 1.2; font-weight: 650; letter-spacing: -0.015em; }
.summary { margin: 0.25rem 0 0; color: var(--muted); font-variant-numeric: tabular-nums; }
.notice { min-height: 1.5em; margin: 0 0 0.5rem; color: var(--ink); font-size: 0.875rem; }
.foot { margin: 1rem 0 0; color: var(--muted); font-size: 0.8125rem; }

/* The status mark: shape carries the state, colour reinforces it */
.mark { display: inline-flex; align-items: center; gap: 0.5em; white-space: nowrap; }
.mark__shape { width: 0.5rem; height: 0.5rem; flex: none; background: currentColor; }
.mark--passed { color: var(--ok); }
.mark--passed .mark__shape { border-radius: 50%; }
.mark--failed { color: var(--bad); font-weight: 600; }
.mark--failed .mark__shape { transform: rotate(45deg); width: 0.45rem; height: 0.45rem; }
.mark--idle { color: var(--idle); }
.mark--idle .mark__shape { background: none; border: 1.5px solid currentColor; border-radius: 50%; }

/* Table */
.table-wrap {
  overflow-x: auto;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 0.5rem;
}
table { width: 100%; min-width: 36rem; border-collapse: collapse; }
th, td { padding: 0.625rem 1rem; text-align: left; white-space: nowrap; }
thead th {
  font-size: 0.8125rem; font-weight: 500; color: var(--muted);
  border-bottom: 1px solid var(--line);
  position: sticky; top: 0; background: var(--surface);
}
tbody tr + tr { border-top: 1px solid var(--line); }
tbody th { font-weight: 400; }
.id { font-family: var(--mono); font-size: 0.8125rem; }
.num { text-align: right; font-variant-numeric: tabular-nums; }
.act { text-align: right; width: 1%; }
@media (hover: hover) { tbody tr:hover { background: var(--hover); } }

/* Buttons: one component, two weights */
.btn {
  font: inherit; font-size: 0.875rem; font-weight: 500;
  min-height: 2rem; padding: 0.25rem 0.875rem;
  border-radius: 0.375rem;
  border: 1px solid var(--edge);
  background: transparent; color: var(--ink);
  cursor: pointer;
  touch-action: manipulation;
  transition: background-color 150ms ease-out, border-color 150ms ease-out;
