/* Failed rows are the ones you retry: that button carries the weight */
.run--failed .retry { border-color: var(--bad); color: var(--bad); }

.empty { padding: 3rem 1rem; text-align: center; background: var(--surface); border: 1px dashed var(--edge); border-radius: 0.5rem; }
.empty p { margin: 0.5rem 0 0; color: var(--muted); }

@media (max-width: 40rem) {
  .bar, main { padding-inline: 1rem; }
  th:first-child { position: sticky; left: 0; background: var(--surface); z-index: 1; }
}
